// Writes src/lib/monsoon/accounts/crm-schema.generated.ts from src/lib/monsoon/testing/0001_init.sql.
// Run after any change to the schema file: node scripts/monsoon/gen_setup_schema.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const sql = readFileSync(join(root, "src", "lib", "monsoon", "testing", "0001_init.sql"), "utf8").replace(/\r\n/g, "\n");
const out =
  "// Generated by scripts/monsoon/gen_setup_schema.mjs from testing/0001_init.sql. Do not edit.\n" +
  `export const CRM_SCHEMA_SQL = ${JSON.stringify(sql)};\n`;
writeFileSync(join(root, "src", "lib", "monsoon", "accounts", "crm-schema.generated.ts"), out);
